{"path": "src/lib/validation.ts", "content": "/* Validation utilities for numeric inputs and backup passphrase.
   Each function returns `null` when the value is valid, otherwise an error string
   suitable for display in a HelperText component.
*/

/** Validate receipt amount: >0, ≤1,000,000, up to 2 decimal places */
export function validateReceiptAmount(value: string): string | null {
  if (!value) return 'Enter a value > 0, ≤ 1 000 000 with up to 2 decimals.';
  const num = Number(value);
  if (isNaN(num) || num <= 0) return 'Enter a value > 0, ≤ 1 000 000 with up to 2 decimals.';
  if (num > 1_000_000) return 'Enter a value > 0, ≤ 1 000 000 with up to 2 decimals.';
  // allow up to two decimal places
  if (!/^\d{1,7}(\.\d{1,2})?$/.test(value)) {
    return 'Enter a value > 0, ≤ 1 000 000 with up to 2 decimals.';
  }
  return null;
}

/** Validate mileage miles: >0, ≤10,000, up to 2 decimals */
export function validateMileageMiles(value: string): string | null {
  if (!value) return 'Enter a value > 0 and ≤ 10 000.';
  const num = Number(value);
  if (isNaN(num) || num <= 0 || num > 10_000) return 'Enter a value > 0 and ≤ 10 000.';
  if (!/^\d{1,5}(\.\d{1,2})?$/.test(value)) {
    return 'Enter a value > 0 and ≤ 10 000.';
  }
  return null;
}

/** Validate mileage rate: 0‑5 dollars per mile */
export function validateMileageRate(value: string): string | null {
  const num = Number(value);
  if (isNaN(num) || num < 0 || num > 5) return 'Enter a value ≥ 0 and ≤ 5 $ per mile.';
  return null;
}

/** Validate tax rate: 0‑100 percent */
export function validateTaxRate(value: string): string | null {
  const num = Number(value);
  if (isNaN(num) || num < 0 || num > 100) return 'Enter a percentage ≥ 0 and ≤ 100.';
  return null;
}

/** Validate backup passphrase: at least 12 characters */
export function validateBackupPassphrase(p: string): string | null {
  if (p.length < 12) return 'Passphrase must be at least 12 characters.';
  return null;
}
"}

{"path": "src/lib/files.ts", "content": "// Saving and picking files on every platform.
// iOS/Android: files are written to the app's cache and handed to the share sheet; picked files are read from
// their local copy. Web: saving downloads the file and picking uses the browser's file chooser (both via the same
// expo APIs, so the UI flow check can save a backup and hand the same file back to restore it).
import * as DocumentPicker from 'expo-document-picker';
import * as Sharing from 'expo-sharing';
import { Platform } from 'react-native';
import * as FileSystem from 'expo-file-system';
import { toBase64, fromBase64 } from './crypto';

/** Save bytes as a file the user can keep: the share sheet on phones, a download on the web. */
export async function saveAndShare(fileName: string, bytes: Uint8Array, mimeType = 'application/octet-stream'): Promise<void> {
  if (Platform.OS === 'web') {
    const blob = new Blob([bytes as BlobPart], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    return;
  }
  const cacheDir = (FileSystem as any).cacheDirectory || '';
  const fileUri = `${cacheDir}${fileName}`;
  const base64 = toBase64(bytes);
  await FileSystem.writeAsStringAsync(fileUri, base64, { encoding: FileSystem.EncodingType.Base64 });
  if (await Sharing.isAvailableAsync()) {
    await Sharing.shareAsync(fileUri, { mimeType, dialogTitle: fileName });
  }
  // Clean up the temporary file after sharing (or if sharing not available)
  try {
    await FileSystem.deleteAsync(fileUri, { idempotent: true });
  } catch {}
}

/** Let the user pick one file; null if they cancel. Call this directly from a button press: browsers only open a
 * file chooser straight from the tap (no awaits, dialogs or navigation before it).
 */
export async function pickFile(): Promise<{ name: string; bytes: Uint8Array } | null> {
  const res = await DocumentPicker.getDocumentAsync({ copyToCacheDirectory: true, multiple: false });
  if (res.canceled || !res.assets?.length) return null;
  const asset = res.assets[0];
  if (Platform.OS === 'web' && asset.file) {
    return { name: asset.name, bytes: new Uint8Array(await asset.file.arrayBuffer()) };
  }
  const base64 = await FileSystem.readAsStringAsync(asset.uri, { encoding: FileSystem.EncodingType.Base64 });
  const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
  return { name: asset.name, bytes };
}

/** Read a file's raw bytes using the new Expo File API (or fallback to readAsStringAsync). */
export async function readFileBytes(uri: string): Promise<Uint8Array> {
  // New API: File object with bytes() method – not available in this runtime, so fallback.
  try {
    // @ts-ignore new File API may exist
    const file = new File(uri);
    // @ts-ignore
    const data: Uint8Array = await file.bytes();
    return data;
  } catch {
    const base64 = await FileSystem.readAsStringAsync(uri, { encoding: FileSystem.EncodingType.Base64 });
    return Uint8Array.from(atob(base64), c => c.charCodeAt(0));
  }
}

/** Write raw bytes to a file using the new Expo File API (or fallback). */
export async function writeFileBytes(uri: string, data: Uint8Array): Promise<void> {
  try {
    // @ts-ignore new File API may exist
    const file = new File(uri);
    // @ts-ignore
    await file.write(data);
  } catch {
    const base64 = toBase64(data);
    await FileSystem.writeAsStringAsync(uri, base64, { encoding: FileSystem.EncodingType.Base64 });
  }
}
"}

{"path": "src/lib/backup.ts", "content": "import type { Store } from './storage/types';
import { keepingPolicy } from './dataReset';
import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import { deriveKey, encrypt, decrypt, toBase64, fromBase64, utf8, fromUtf8, randomBytes } from './crypto';
import type { Receipt, MileageEntry } from './models';
import * as FileSystem from 'expo-file-system';
import { readFileBytes, writeFileBytes } from './files';
import { validateBackupPassphrase } from './validation';

const MIN_LENGTH = 12;
/** Validate passphrase policy */
function enforcePassphrasePolicy(p: string): void {
  const err = validateBackupPassphrase(p);
  if (err) throw new Error(`Invalid backup passphrase: ${err}`);
}

/** Create an encrypted backup of all data, including receipt photos.
 * Returns a base64‑encoded string representing the encrypted payload.
 */
export async function createBackup(store: Store, passphrase: string): Promise<string> {
  enforcePassphrasePolicy(passphrase);
  const receipts: Receipt[] = await getAllReceipts(store);
  const mileage: MileageEntry[] = await getAllMileageEntries(store);
  const receiptsWithPhotos = await Promise.all(
    receipts.map(async (r) => {
      if (r.photoUri) {
        try {
          const bytes = await readFileBytes(r.photoUri);
          const b64 = toBase64(bytes);
          return { ...r, photoData: b64 };
        } catch {
          return { ...r };
        }
      }
      return { ...r };
    })
  );
  const payload = JSON.stringify({ receipts: receiptsWithPhotos, mileage });
  const salt = randomBytes(16);
  const key = deriveKey(passphrase, salt);
  const encrypted = encrypt(key, utf8(payload));
  const combined = new Uint8Array(salt.length + encrypted.length);
  combined.set(salt, 0);
  combined.set(encrypted, salt.length);
  return toBase64(combined);
}

/** Validate the structure of a decrypted backup. */
function validateBackupStructure(data: any): string | null {
  if (typeof data !== 'object' || data === null) return 'Backup data is not an object.';
  if (typeof data.version !== 'number') return 'Missing or invalid version.';
  if (!Array.isArray(data.receipts)) return 'Receipts should be an array.';
  if (!Array.isArray(data.mileage)) return 'Mileage should be an array.';
  // Simple field checks for receipts
  for (const r of data.receipts) {
    if (typeof r.id !== 'string' || typeof r.amount !== 'number' || typeof r.date !== 'string')
      return 'Invalid receipt entry.';
  }
  for (const m of data.mileage) {
    if (typeof m.id !== 'string' || typeof m.date !== 'string' || typeof m.miles !== 'number')
      return 'Invalid mileage entry.';
  }
  return null;
}

/** Restore data from an encrypted backup blob.
 * Throws an error with a friendly message if the passphrase is wrong or the file is corrupted.
 */
export async function restoreBackup(store: Store, backupBlob: string, passphrase: string): Promise<void> {
  const combined = fromBase64(backupBlob);
  if (combined.length < 16) throw new Error('Invalid backup file');
  const salt = combined.subarray(0, 16);
  const ciphertext = combined.subarray(16);
  const key = deriveKey(passphrase, salt);
  let decrypted: string;
  try {
    decrypted = fromUtf8(decrypt(key, ciphertext));
  } catch {
    throw new Error('Invalid passphrase or corrupted backup file');
  }
  const data = JSON.parse(decrypted) as any;

  // Validate structure before mutating store
  const structErr = validateBackupStructure(data);
  if (structErr) throw new Error('Invalid backup format: ' + structErr);

  const cacheDir = (FileSystem as unknown as any).cacheDirectory ?? '';
  try {
    const entries = await FileSystem.readDirectoryAsync(cacheDir);
    await Promise.all(entries.map((e) => FileSystem.deleteAsync(`${cacheDir}${e}`, { idempotent: true })));
  } catch {}

  await keepingPolicy(store, async () => {
    await store.clearAll();
    for (const r of data.receipts) {
      const { photoData, ...rest } = r as any;
      await store.put('receipts', rest as any);
      if (photoData) {
        const uri = `${cacheDir}${rest.id}_photo`;
        try {
          const bytes = Uint8Array.from(atob(photoData), c => c.charCodeAt(0));
          await writeFileBytes(uri, bytes);
          await store.put('receipts', { ...rest, photoUri: uri } as any);
        } catch {}
      }
    }
    for (const m of data.mileage) {
      await store.put('mileage', m as any);
    }
  });
}
"}

{"path": "src/screens/ReceiptEntryScreen.tsx", "content": "import React, { useState } from 'react';
import { View } from 'react-native';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { PrimaryButton, Screen, FormField, ChoiceField } from '../components/ui';
import { addReceipt } from '../lib/receiptStore';
import { getStore } from '../lib/storage';
import { Receipt, ReceiptType } from '../lib/models';
import { Snackbar } from 'react-native-paper';
import { setPendingSnack } from '../lib/uiState';
import ReceiptImagePicker from '../components/ui/ReceiptImagePicker';
import { v4 as uuidv4 } from 'uuid';
import { validateReceiptAmount } from '../lib/validation';

export default function ReceiptEntryScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [type, setType] = useState<ReceiptType>('expense');
  const [notes, setNotes] = useState('');
  const [photoUri, setPhotoUri] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string>('');
  const [saving, setSaving] = useState(false);

  const amountError = validateReceiptAmount(amount);

  const validate = () => {
    if (amountError) return amountError;
    if (!date) return 'Select a date.';
    if (!category) return 'Choose a category.';
    if (!type) return 'Select expense or income.';
    return '';
  };

  const onSave = async () => {
    const err = validate();
    if (err) {
      setError(err);
      return;
    }
    setError('');
    setSaving(true);
    const receipt: Receipt = {
      id: uuidv4(),
      amount: Number(amount),
      date,
      category,
      type,
      notes,
      photoUri,
    };
    try {
      await addReceipt(getStore(), receipt);
      setPendingSnack('Receipt saved');
      navigation.navigate('Main', { screen: 'Dashboard' });
    } catch (e) {
      setError('Unable to save receipt. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  const canSave = !saving && validate() === '' && !amountError;

  return (
    <Screen title="Add receipt">
      <View style={{ gap: 12 }}>
        <ReceiptImagePicker photoUri={photoUri} onChange={setPhotoUri} />
        <FormField label="Amount" value={amount} onChangeText={setAmount} keyboardType="numeric" error={amountError} />
        <FormField label="Date" value={date} onChangeText={setDate} placeholder="YYYY-MM-DD" />
        <FormField label="Category" value={category} onChangeText={setCategory} />
        <ChoiceField<ReceiptType>
          label="Type"
          value={type}
          onChange={setType}
          options={[{ value: 'expense', label: 'Expense' }, { value: 'income', label: 'Income' }]}
        />
        <FormField label="Notes" value={notes} onChangeText={setNotes} multiline />
        {error ? <Snackbar visible={true} onDismiss={() => setError('')} duration={3000}>{error}</Snackbar> : null}
        <PrimaryButton label="Save receipt" onPress={onSave} loading={saving} disabled={!canSave} />
      </View>
    </Screen>
  );
}
"}

{"path":"src/screens/BackupPassphraseScreen.tsx","content":"import React, { useState } from 'react';
import { HelperText, Text } from 'react-native-paper';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { FormField, PrimaryButton, Screen } from '../components/ui';
import { createBackup } from '../lib/backup';
import { utf8 } from '../lib/crypto';
import { saveAndShare } from '../lib/files';
import { getStore } from '../lib/storage';
import { validateBackupPassphrase } from '../lib/validation';

export default function BackupPassphraseScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [pass1, setPass1] = useState('');
  const [pass2, setPass2] = useState('');
  const [error, setError] = useState<string>('');
  const [busy, setBusy] = useState(false);

  const passwordsMatch = pass1 && pass2 && pass1 === pass2;
  const passphraseError = error || (pass1 && validateBackupPassphrase(pass1)) || (!passwordsMatch && pass1 && pass2 && "Passphrases must match.");

  const canCreate = !busy && pass1 && pass2 && passwordsMatch && !validateBackupPassphrase(pass1);

  const create = async () => {
    setError('');
    setBusy(true);
    try {
      const backup = await createBackup(getStore(), pass1);
      await saveAndShare(`finance-backup-${new Date().toISOString().slice(0,10)}.backup`, utf8(backup));
      navigation.navigate('backup_success');
    } catch (e:any) {
      setError(e.message ?? 'The backup could not be created. Please try again.');
    } finally {
      setBusy(false);
    }
  };

  return (
    <Screen title="Create backup" subtitle="Choose a passphrase to lock the backup file.">
      <Text variant="bodyMedium" style={{ marginBottom: 8 }}>Passphrase must be at least 12 characters.</Text>
      <FormField
        label="Backup passphrase"
        value={pass1}
        onChangeText={setPass1}
        secureTextEntry
        autoCapitalize="none"
        accessibilityLabel="Backup passphrase"
      />
      <FormField
        label="Confirm passphrase"
        value={pass2}
        onChangeText={setPass2}
        secureTextEntry
        autoCapitalize="none"
        accessibilityLabel="Confirm passphrase"
      />
      {passphraseError ? <HelperText type="error">{passphraseError}</HelperText> : null}
      <PrimaryButton label="Create backup" onPress={create} loading={busy} disabled={!canCreate} />
    </Screen>
  );
}
"}

{"path": "src/screens/MileageEntryScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { Card, Text, TextInput } from 'react-native-paper';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { FormField, PrimaryButton, Screen } from '../components/ui';
import { calculateMileageDeduction } from '../lib/mileage';
import { addMileageEntry } from '../lib/mileageStore';
import { MileageEntry } from '../lib/models';
import { DEFAULT_MILEAGE_RATE, getMileageRate } from '../lib/settings';
import { getStore } from '../lib/storage';
import { setPendingSnack } from '../lib/uiState';
import { space, theme } from '../theme';
import { validateMileageMiles } from '../lib/validation';

const today = () => new Date().toISOString().slice(0, 10);
const money = (n: number) => `$${n.toFixed(2)}`;
const perMile = (n: number) => `$${n.toFixed(3).replace(/0$/, '')}`;

/** Log one business trip. Errors show under their field when Save is pressed; the deduction updates as you type. */
export default function MileageEntryScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [date, setDate] = useState(today());
  const [miles, setMiles] = useState('');
  const [purpose, setPurpose] = useState('');
  const [rate, setRate] = useState(DEFAULT_MILEAGE_RATE);
  const [errors, setErrors] = useState<{ date?: string; miles?: string; purpose?: string; save?: string }>({});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    getMileageRate(getStore()).then(setRate).catch(() => {});
  }, []);

  const milesNumber = Number(miles);
  const deduction = miles && !isNaN(milesNumber) && milesNumber > 0 ? calculateMileageDeduction(milesNumber, rate) : 0;

  const validate = () => {
    const e: typeof errors = {};
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) e.date = 'Use the format YYYY-MM-DD.';
    const milesErr = validateMileageMiles(miles);
    if (milesErr) e.miles = milesErr;
    if (!purpose.trim()) e.purpose = 'Say what the trip was for.';
    return e;
  };

  const onSave = async () => {
    const e = validate();
    setErrors(e);
    if (Object.keys(e).length) return;
    setSaving(true);
    const entry: MileageEntry = { id: `${Date.now()}-${Math.random()}`, date, miles: milesNumber, purpose: purpose.trim() };
    try {
      await addMileageEntry(getStore(), entry);
      setPendingSnack('Mileage saved');
      navigation.navigate('Main', { screen: 'Dashboard' });
    } catch {
      setErrors({ save: "The trip couldn't be saved. Please try again." });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Screen subtitle="Log a business trip. Keep a record of every trip for your tax year.">
      <Card mode="elevated" style={styles.card}>
        <Card.Content style={styles.form}>
          <FormField label="Date" value={date} onChangeText={setDate} error={errors.date} hint="YYYY-MM-DD" autoComplete="off" />
          <FormField label="Miles" value={miles} onChangeText={setMiles} error={errors.miles} keyboardType="decimal-pad"
            right={<TextInput.Affix text="mi" />} />
          <FormField label="Purpose" value={purpose} onChangeText={setPurpose} error={errors.purpose} hint="e.g. Client site visit" />
        </Card.Content>
      </Card>
      <Card mode="outlined" style={[styles.card, styles.preview]}>
        <Card.Content style={styles.previewContent}>
          <View style={styles.previewText}>
            <Text variant="labelLarge" style={styles.muted}>Deduction for this trip</Text>
            <Text variant="bodySmall" style={styles.muted}>At {perMile(rate)} per mile (change it in Settings)</Text>
          </View>
          <Text variant="headlineSmall" style={styles.amount}>{money(deduction)}</Text>
        </Card.Content>
      </Card>
      {errors.save ? <Text variant="bodyMedium" style={styles.error}>{errors.save}</Text> : null}
      <PrimaryButton label="Save mileage" onPress={onSave} loading={saving} disabled={saving} />
    </Screen>
  );
}

const styles = StyleSheet.create({
  card: { backgroundColor: theme.colors.surface },
  form: { gap: space(2), paddingVertical: space(2) },
  preview: { backgroundColor: theme.colors.primaryContainer },
  previewContent: { flexDirection: 'row', alignItems: 'center', gap: space(2), paddingVertical: space(1.5) },
  previewText: { flex: 1, gap: space(0.5) },
  muted: { color: theme.colors.onPrimaryContainer },
  amount: { fontWeight: '700', color: theme.colors.onPrimaryContainer },
  error: { color: theme.colors.error },
});
"}

