{"path": "__tests__/dataReset.test.ts", "content": "import { createStore, createMemoryRawStore, createMemoryKeyProvider } from '../src/lib/storage/memory';
import { acceptPolicy, getPolicyAcceptance, isPolicyAccepted } from '../src/lib/policy';
import { clearAllData } from '../src/lib/dataReset';
import * as SecureStore from 'expo-secure-store';

jest.mock('expo-secure-store');

const KEY_NAME = 'app.data-key.v1';

test('clearAllData deletes encryption key and preserves policy acceptance', async () => {
  const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());
  // set policy accepted
  await acceptPolicy(store);
  // set a key in SecureStore
  await SecureStore.setItemAsync(KEY_NAME, 'secret');

  await clearAllData(store);

  // policy still accepted
  expect(await isPolicyAccepted(store)).toBe(true);
  // key should be deleted
  const key = await SecureStore.getItemAsync(KEY_NAME);
  expect(key).toBeNull();
});
"}

{"path": "src/components/ui/FABAdd.tsx", "content": "import React, { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { FAB, Portal } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { theme, space } from '../../theme';
import { useNavigation, NavigationProp } from '@react-navigation/native';

/** FAB that opens mini-FABs for adding a receipt or mileage entry.
 * The main FAB has an accessible label "Add".
 * Mini FABs are labelled "Receipt" and "Mileage".
 */
export default function FABAdd() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [open, setOpen] = useState(false);

  const toggle = () => setOpen((prev) => !prev);

  const goToReceipt = () => {
    navigation.getParent?.()?.navigate('ReceiptEntry');
    setOpen(false);
  };

  const goToMileage = () => {
    navigation.getParent?.()?.navigate('MileageEntry');
    setOpen(false);
  };

  const receiptIcon = ({ size, color }: { size: number; color: string }) => (
    <MaterialCommunityIcons name="receipt" size={size} color={color} aria-hidden />
  );
  const mileageIcon = ({ size, color }: { size: number; color: string }) => (
    <MaterialCommunityIcons name="run" size={size} color={color} aria-hidden />
  );

  return (
    <Portal>
      <View style={styles.container} pointerEvents="box-none">
        {open && (
          <View style={styles.miniContainer}>
            <FAB
              style={styles.miniFab}
              small
              icon={receiptIcon}
              accessibilityLabel="Receipt"
              accessibilityRole="button"
              onPress={goToReceipt}
              color={theme.colors.onSecondary}
              theme={{ colors: { accent: theme.colors.secondary } }}
            />
            <FAB
              style={styles.miniFab}
              small
              icon={mileageIcon}
              accessibilityLabel="Mileage"
              accessibilityRole="button"
              onPress={goToMileage}
              color={theme.colors.onSecondary}
              theme={{ colors: { accent: theme.colors.secondary } }}
            />
          </View>
        )}
        <FAB
          style={styles.fab}
          icon="plus"
          accessibilityLabel="Add"
          accessibilityRole="button"
          onPress={toggle}
          color={theme.colors.onSecondary}
          theme={{ colors: { accent: theme.colors.secondary } }}
        />
      </View>
    </Portal>
  );
}

const styles = StyleSheet.create({
  container: { position: 'absolute', bottom: space(2), right: space(2), alignItems: 'center' },
  fab: { elevation: 4 },
  miniContainer: { marginBottom: 8, flexDirection: 'column-reverse', alignItems: 'center' },
  miniFab: { marginBottom: 8 },
});
"}

{"path": "src/screens/DashboardScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Snackbar, Text } from 'react-native-paper';
import { FlatList, View } from 'react-native';
import { useNavigation, useRoute, NavigationProp, RouteProp } from '@react-navigation/native';
import { EmptyState, Screen, SummaryCard } from '../components/ui';
import { getStore } from '../lib/storage';
import { Receipt, MileageEntry } from '../lib/models';
import { getAllReceipts } from '../lib/receiptStore';
import { getAllMileageEntries } from '../lib/mileageStore';
import { computeTotals } from '../lib/finance';
import { totalMileageDeduction } from '../lib/mileage';
import { getTaxRate } from '../lib/settings';
import ReceiptCard from '../components/ui/ReceiptCard';
import { consumeSnack } from '../lib/uiState';
import FABAdd from '../components/ui/FABAdd';
import { space } from '../theme';

type DashboardRouteParams = {};

export default function DashboardScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const route = useRoute<RouteProp<Record<string, DashboardRouteParams>, string>>();
  const [loading, setLoading] = useState(true);
  const [receipts, setReceipts] = useState<Receipt[]>([]);
  const [mileageEntries, setMileageEntries] = useState<MileageEntry[]>([]);
  const [mileageDeduction, setMileageDeduction] = useState<number>(0);
  const [tax, setTax] = useState<number>(0);
  const [snack, setSnack] = useState<string>('');

  const load = async () => {
    setLoading(true);
    const store = getStore();
    const recs = await getAllReceipts(store);
    const miles = await getAllMileageEntries(store);
    setReceipts(recs);
    setMileageEntries(miles);
    const deduction = await totalMileageDeduction(miles);
    setMileageDeduction(deduction);
    const taxRate = await getTaxRate(store);
    const totals = computeTotals(recs);
    const taxable = Math.max(0, totals.income - totals.expenses - deduction);
    setTax(taxable * taxRate);
    setLoading(false);
    const pending = consumeSnack();
    if (pending) setSnack(pending);
  };

  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', load);
    return unsubscribe;
  }, [navigation]);

  if (loading) {
    return <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading" />;
  }

  const totals = computeTotals(receipts);

  const empty = receipts.length === 0 && mileageEntries.length === 0;

  return (
    <Screen title="Dashboard" wide>
      {empty ? (
        <EmptyState
          icon="inbox-outline"
          title="Nothing here yet"
          body="Add a receipt or mileage entry to start tracking your finances."
        />
      ) : (
        <View style={{ gap: 16 }}>
          <View style={{ flexDirection: 'row', gap: 8, flexWrap: 'wrap' }}>
            <SummaryCard label="Income" value={`$${totals.income.toFixed(2)}`} />
            <SummaryCard label="Expenses" value={`$${totals.expenses.toFixed(2)}`} />
            <SummaryCard label="Mileage deduction" value={`$${mileageDeduction.toFixed(2)}`} />
            <SummaryCard label="Estimated tax" value={`$${tax.toFixed(2)}`} />
          </View>
          <Text variant="titleMedium" style={{ marginTop: 8, marginBottom: 4 }}>Recent activity</Text>
          <FlatList
            data={receipts.slice(0, 5)}
            keyExtractor={(item) => item.id}
            renderItem={({ item }) => <ReceiptCard receipt={item} />}
          />
        </View>
      )}
      {snack ? (
        <Snackbar
          visible={true}
          onDismiss={() => setSnack('')}
          duration={3000}
          style={{ bottom: space(14) }}
        >
          {snack}
        </Snackbar>
      ) : null}
      <FABAdd />
    </Screen>
  );
}
"}

