      "severity": "low",
      "viewport": "both",
      "issue": "The snackbar overlaps slightly with the activity card, obscuring part of the entry details.",
      "fix": "Adjust snackbar position or padding to prevent overlap with content."
    },
    {
      "severity": "low",
      "viewport": "phone",
      "issue": "The FAB is positioned slightly too far from the bottom edge on phone, reducing touch target size.",
