# Helper functions
# ----------------------------------------------------------------------
def write_test_file(path: Path, content: str) -> None:
    """Write a test file, ensuring its parent directory exists."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")

def generate_tests(limit: int | None) -> None:
    """Create Jest test files for the requested milestones."""
    for milestone, files in MILESTONE_TESTS.items():
        if limit is not None and milestone > limit:
            continue
        for filename, content in files:
            write_test_file(TESTS_DIR / filename, content)

def ensure_node_modules() -> None:
    """Run `npm install` if the `node_modules` directory is absent."""
    if (PROJECT_ROOT / "node_modules").is_dir():
        return
    print("⚙️  node_modules not found – installing dependencies with `npm install`...")
    try:
        subprocess.run(
            ["npm", "install"],
            cwd=PROJECT_ROOT,
            check=True,
            stdout=sys.stdout,
            stderr=sys.stderr,
            timeout=600,
        )
    except subprocess.CalledProcessError as exc:
        print(f"❌ npm install failed (exit code {exc.returncode})")
        sys.exit(1)

def run_jest(limit: int | None) -> int:
    """Execute Jest, optionally filtering by milestone."""
    # Run all Jest tests (acceptance + unit) so the new hardening checks are exercised.
    jest_cmd = ["npx", "jest", "--ci"]
    if limit is not None:
        allowed = "|".join(f"M{i}" for i in range(1, limit + 1))
        pattern = f"^({allowed}): "
        jest_cmd.extend(["-t", pattern])
    print(f"[RUN] Running Jest: {' '.join(jest_cmd)}")
    result = subprocess.run(
        jest_cmd,
        cwd=PROJECT_ROOT,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        timeout=600,
    )
    print(result.stdout)
    return result.returncode

def main() -> None:
    # Determine which milestones to run
    env_val = os.getenv("ACCEPTANCE_MILESTONE")
    limit: int | None = None
    if env_val:
        try:
            limit = int(env_val)
            if limit < 1:
                raise ValueError()
        except ValueError:
            print(
                "⚠️  Invalid ACCEPTANCE_MILESTONE – must be a positive integer.",
                file=sys.stderr,
            )
            sys.exit(2)

    # 1️⃣ Generate the Jest test files
    generate_tests(limit)

    # 2️⃣ Ensure npm dependencies are installed
    ensure_node_modules()

    # 3️⃣ Run Jest (all tests, filtered by milestone if requested)
    exit_code = run_jest(limit)

    if exit_code == 0:
        print("✅ All acceptance tests passed.")
    else:
        print(f"❌ Acceptance tests failed (exit code {exit_code}).")
    sys.exit(exit_code)

if __name__ == "__main__":
    main()
"}

{"path": "src/components/ui/FABAdd.tsx", "content": "import React, { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { FAB, Portal } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { theme, space } from '../../theme';
import { useNavigation, NavigationProp } from '@react-navigation/native';

/** FAB that opens mini-FABs for adding a receipt or mileage entry.
 * The main FAB has an accessible label "Add".
 * Mini FABs are labelled "Add receipt" and "Mileage" for compatibility with UI flow.
 */
export default function FABAdd() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [open, setOpen] = useState(false);

  const toggle = () => setOpen((prev) => !prev);

  const goToReceipt = () => {
    navigation.getParent?.()?.navigate('ReceiptEntry');
    setOpen(false);
  };

  const goToMileage = () => {
    navigation.getParent?.()?.navigate('MileageEntry');
    setOpen(false);
  };

  const receiptIcon = ({ size, color }: { size: number; color: string }) => (
    <MaterialCommunityIcons name="receipt" size={size} color={color} aria-hidden />
  );
  const mileageIcon = ({ size, color }: { size: number; color: string }) => (
    <MaterialCommunityIcons name="run" size={size} color={color} aria-hidden />
  );

  return (
    <>
      {/* Mini FABs rendered in a separate portal */}
      {open && (
        <Portal>
          <View style={styles.miniContainer} pointerEvents="box-none">
            <FAB
              style={styles.miniFab}
              small
              icon={receiptIcon}
              accessibilityLabel="Add receipt"
              accessibilityRole="button"
              onPress={goToReceipt}
              color={theme.colors.onSecondary}
              theme={{ colors: { accent: theme.colors.secondary } }}
            />
            <FAB
              style={styles.miniFab}
              small
              icon={mileageIcon}
              accessibilityLabel="Mileage"
              accessibilityRole="button"
              onPress={goToMileage}
              color={theme.colors.onSecondary}
              theme={{ colors: { accent: theme.colors.secondary } }}
            />
          </View>
        </Portal>
      )}
      {/* Main FAB */}
      <Portal>
        <View style={styles.container} pointerEvents="box-none">
          <FAB
            style={styles.fab}
            icon="plus"
            accessibilityLabel="Add"
            accessibilityRole="button"
            onPress={toggle}
            color={theme.colors.onSecondary}
            theme={{ colors: { accent: theme.colors.secondary } }}
          />
        </View>
      </Portal>
    </>
  );
}

const styles = StyleSheet.create({
  container: { position: 'absolute', bottom: space(2), right: space(2), alignItems: 'center' },
  fab: { elevation: 4 },
  miniContainer: { position: 'absolute', bottom: space(10), right: space(2), alignItems: 'center' },
  miniFab: { marginBottom: 8 },
});
"}

