        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        timeout=600,
    )
    print(result.stdout)
    return result.returncode

def main() -> None:
    env_val = os.getenv("ACCEPTANCE_MILESTONE")
    limit: int | None = None
    if env_val:
        try:
            limit = int(env_val)
            if limit < 1:
                raise ValueError()
        except ValueError:
            print("\u26a0\ufe0f  Invalid ACCEPTANCE_MILESTONE \u2013 must be a positive integer.", file=sys.stderr)
            sys.exit(2)
    generate_tests(limit)
    ensure_node_modules()
    exit_code = run_jest(limit)
    if exit_code == 0:
        print("\u2705 All acceptance tests passed.")
    else:
        print(f"\u274c Acceptance tests failed (exit code {exit_code}).")
    sys.exit(exit_code)

if __name__ == "__main__":
    main()
"}

